*{box-sizing:border-box}
 :root{font-family:'Outfit',sans-serif;color:#f5f4ff;background:#090b1a;font-synthesis:none;font-optical-sizing:auto}
 body{margin:0;min-width:320px;min-height:100vh;background:#090b1a}
 button,input{font:inherit}
.game-shell{height:100svh;min-height:650px;padding:12px}
.viewport{height:100%;width:100%;position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.09);border-radius:18px;background:radial-gradient(ellipse at 50% 46%,#28304d 0%,#11172d 44%,#090b1a 100%);isolation:isolate}
#scene-host{position:absolute;inset:0;z-index:0}
#scene-host canvas{display:block;width:100%;height:100%;outline:0}
.sky-glow{position:absolute;z-index:1;pointer-events:none;inset:0;background:radial-gradient(ellipse at 48% 48%,transparent 25%,rgba(8,10,26,.1) 63%,rgba(8,10,24,.5) 100%)}
.scene-vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:linear-gradient(180deg,rgba(8,10,23,.7) 0%,transparent 19%,transparent 63%,rgba(8,10,23,.58) 100%)}
.topbar{height:64px;position:absolute;top:0;left:0;right:0;z-index:3;display:flex;align-items:center;justify-content:space-between;padding:0 31px;border-bottom:1px solid rgba(255,255,255,.08);background:linear-gradient(180deg,rgba(8,10,22,.58),rgba(8,10,22,.12))}
.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font-size:14px;font-weight:800;letter-spacing:2px}
.brand-mark{display:grid;place-items:center;width:27px;height:27px;border:1px solid rgba(255,204,94,.6);border-radius:8px;color:#ffd165;font-size:17px}
.brand-dot{color:#ff6581}
.top-center,.weather{font:10px 'DM Mono',monospace;letter-spacing:1.15px;color:#b8bed3;display:flex;align-items:center;gap:12px}
.top-center i{height:12px;width:1px;background:#ffffff30}
.live-dot,.status-dot{height:7px;width:7px;border-radius:50%;background:#7df2ba;box-shadow:0 0 11px #74ffb2}
.weather{gap:9px}
